import{_ as o,o as r,c as d,ag as n}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"天涯神贴 ↔ 毛泽东思想：逐条对照与核实","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/mao-zedong/tianya-maoism-mapping.md","filePath":"topics/mao-zedong/tianya-maoism-mapping.md"}'),s={name:"topics/mao-zedong/tianya-maoism-mapping.md"};function g(e,t,a,c,h,i){return r(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="天涯神贴-↔-毛泽东思想-逐条对照与核实" tabindex="-1">天涯神贴 ↔ 毛泽东思想：逐条对照与核实 <a class="header-anchor" href="#天涯神贴-↔-毛泽东思想-逐条对照与核实" aria-label="Permalink to &quot;天涯神贴 ↔ 毛泽东思想：逐条对照与核实&quot;">​</a></h1><blockquote><p><strong>来源</strong>：用户 2026-11-06 对照长文（核心命题：「那批天涯幸存者，在不知道毛泽东的情况下，用真金白银重新发明了一半毛泽东思想」） <strong>主题</strong>：跨域方法论迁移 / 毛选认识论 / 天涯神贴 / 引用核实勘误 关键词：毛泽东思想, 毛选, 论持久战, 亡国论, 速胜论, 十六字诀, 存人失地, 阶级分析, 利益分析法, 实践论, 反对本本主义, 调查研究, 持久战, 失效条件, 公理检验法, 可证伪性, 时间错位, 程度夸大, 指标拼接, 核验方法, 信源核实, 民间史论, 预言命中率, 天涯神贴, kkndme, 土地财政, 杠杆爆仓 <strong>核实方法</strong>：</p><ul><li><strong>毛著侧</strong>：逐字核对 <strong>中文马克思主义文库</strong> <code>marxists.org/chinese/maozedong/</code> 原文（附篇名 + 日期 + 命中次数），非凭记忆。</li><li><strong>天涯侧</strong>：锚回本库 <code>topics/tianya/handbook/</code>（附帖号）。 <strong>核实结论</strong>：6 条主干对照<strong>全部成立</strong>；但 <strong>4 处引用需修正</strong>（1 处年份错位 19 年、1 处数字搬家、1 处帖号错、1 处年份微调）；<strong>1 处（「存人失地」）未能在毛选标准篇目定位</strong>，属流传性概括。详见 §三 勘误表。</li></ul></blockquote><hr><h2 id="一、命题-为什么说-重新发明" tabindex="-1">一、命题：为什么说&quot;重新发明&quot; <a class="header-anchor" href="#一、命题-为什么说-重新发明" aria-label="Permalink to &quot;一、命题：为什么说&quot;重新发明&quot;&quot;">​</a></h2><p>2005–2020 的天涯财经帖里，一批人在<strong>没有读过毛选</strong>的前提下，用真金白银摸索出一套<strong>认识复杂系统</strong>的方法：辨利益、抓主要矛盾、分阶段、留本金。而毛泽东 1925–1949 在战争与革命中提炼的，正是同一套认识论。</p><p><strong>这不是&quot;天涯抄毛&quot;</strong>（他们没抄），<strong>也不是&quot;毛说了炒股&quot;</strong>（他没说）。是<strong>同一类问题逼出同一套方法</strong>：面对一个信息不全、对手强大、资源有限、时间漫长的复杂系统，如何在看不清全貌时做出<strong>结构上正确</strong>的判断。</p><p>本文把这份对照<strong>逐条锚到原文</strong>，把成立的部分与需要修正的部分分开——因为&quot;像&quot;不等于&quot;是&quot;，引用精度是这套方法论能否迁移的前提。</p><hr><h2 id="二、六条主干对照-逐条核验" tabindex="-1">二、六条主干对照（逐条核验） <a class="header-anchor" href="#二、六条主干对照-逐条核验" aria-label="Permalink to &quot;二、六条主干对照（逐条核验）&quot;">​</a></h2><h3 id="一、阶级分析-↔-利益分析-✅" tabindex="-1">一、阶级分析 ↔ 利益分析 ✅ <a class="header-anchor" href="#一、阶级分析-↔-利益分析-✅" aria-label="Permalink to &quot;一、阶级分析 ↔ 利益分析 ✅&quot;">​</a></h3><p><strong>用户原述</strong>：《中国社会各阶级的分析》开篇「谁是我们的敌人？谁是我们的朋友？这个问题是革命的首要问题」↔ KK 三部曲开篇「辨别利益是看透一切事物真相的武器」。</p><table tabindex="0"><thead><tr><th>侧</th><th>证据</th></tr></thead><tbody><tr><td>毛著侧</td><td>《中国社会各阶级的分析》（1925-12）<strong>逐字命中</strong>：「谁是我们的敌人？谁是我们的朋友？这个问题是革命的首要问题。中国过去一切革命斗争成效甚少，其基本原因就是因为不能团结真正的朋友，以攻击真正的敌人。」</td></tr><tr><td>天涯侧</td><td>手册 <code>01</code> §核心公理**【K1】**「辨别利益是看透一切事物真相的武器」<strong>逐字命中</strong>；源头标注为 <strong>帖 5（kkndme）</strong>。手册把动作拆成 7 类利益主体：中央 / 地方政府 / 银行 / 开发商 / 炒房客 / 有房者 / 无房刚需。</td></tr></tbody></table><p><strong>判定</strong>：同一方法论动作 —— <strong>把复杂系统拆成利益主体，列出各自主目标函数，主要矛盾自己浮出来</strong>。成立。</p><blockquote><p>⚠ <strong>一处转述需标注</strong>：用户版「高房价谁是受益者？诸侯、开发商、炒房客——独独缺了中央」中，「诸侯」是手册「地方政府」的<strong>文学化转述</strong>（手册原文：「地方政府（卖地净赚、无风险）、开发商、炒房客全部受益，唯独中央不受益，还独家承担金融风险」）。<strong>方向与主体一致，非逐字</strong>。</p></blockquote><p><strong>天涯侧的深层同构</strong>：手册 <code>02</code> 第七节【41】把空军病理标本化 —— 「把判断外包给网红空军（牛刀），空军自己在北京上海深圳都有房」—— 这正是《反对本本主义》「没有调查，没有发言权」的<strong>反面病例</strong>：引用的是别人的结论，从没去售楼处数过挂牌量。</p><hr><h3 id="二、《论持久战》↔「方向对、时点错」最大死因-✅" tabindex="-1">二、《论持久战》↔「方向对、时点错」最大死因 ✅ <a class="header-anchor" href="#二、《论持久战》↔「方向对、时点错」最大死因-✅" aria-label="Permalink to &quot;二、《论持久战》↔「方向对、时点错」最大死因 ✅&quot;">​</a></h3><p><strong>用户原述</strong>：毛 1938 年批的<strong>速胜论</strong>与<strong>亡国论</strong>，恰好是天涯里两批亏得最惨的人 —— 亡国论=永远看空（空军踏空十年，北京从一万等到八万）；速胜论=抄底抄在半山腰。</p><table tabindex="0"><thead><tr><th>侧</th><th>证据</th></tr></thead><tbody><tr><td>毛著侧</td><td>《论持久战》（1938-05）<strong>逐字命中</strong>：「<strong>亡国论</strong>」24 次、「<strong>速胜论</strong>」7 次、「<strong>三个阶段</strong>」5 次。原文：「有亡国论和速胜论的反对意见……抗日战争十个月的经验，尽够击破毫无根据的亡国论，也尽够说服急性朋友们的速胜论了。」</td></tr><tr><td>天涯侧</td><td>手册 <code>04</code> §一 命中率分层：<strong>结构层约 7–8 成</strong>、<strong>点位层仅约 3 成</strong>。点位层几乎全军覆没（7 上证 1900–2100 / 6 纳指 8500 见顶 / 4 A股一万点 / 9 铁龙 40 元 全部落空），<strong>唯一命中是 11（老仇 2020-03-01）</strong>。</td></tr></tbody></table><p><strong>判定</strong>：成立。《论持久战》批的两种错法，就是&quot;方向对但早 3 年&quot;与&quot;永远看空&quot;的<strong>认识论尸检</strong>：速胜论死于低估时间，亡国论死于低估约束的韧性。</p><p><strong>三阶段对照</strong>（原文核）：毛的三阶段是 —— 「第一个阶段，是敌之战略<strong>进攻</strong>、我之战略<strong>防御</strong>的时期；第二个阶段，是敌之战略<strong>保守</strong>、我之<strong>准备反攻</strong>的时期；第三个阶段，是我之战略<strong>反攻</strong>、敌之战略<strong>退却</strong>的时期」。用户写的「防御—相持—反攻」是<strong>通行简称</strong>（「相持阶段」为后来通用说法），<strong>不构成失真</strong>。</p><blockquote><p>⚠ <strong>一处年份错位 19 年（必须修正）</strong>：用户把「<strong>战略上藐视敌人，战术上重视敌人</strong>」放在《论持久战》（1938）段落里。 核实：《论持久战》全文 <strong>「藐视」零命中</strong>。该语出自 <strong>1957 年《一切反动派都是纸老虎》</strong>：「在战略上我们要藐视一切敌人，在战术上我们要重视一切敌人。也就是说在整体上我们一定要藐视它，在一个一个的具体问题上我们一定要重视它。」 ——<strong>原话极准，但年份错位 19 年</strong>。这句对交易纪律极重要（方向可以大胆，每笔必须苛刻），<strong>出处标注错了会削弱它的分量</strong>。</p></blockquote><hr><h3 id="三、「存人失地-人地皆得」↔-本金是-人-、浮盈是-地-⚠" tabindex="-1">三、「存人失地，人地皆得」↔ 本金是&quot;人&quot;、浮盈是&quot;地&quot; ⚠ <a class="header-anchor" href="#三、「存人失地-人地皆得」↔-本金是-人-、浮盈是-地-⚠" aria-label="Permalink to &quot;三、「存人失地，人地皆得」↔ 本金是&quot;人&quot;、浮盈是&quot;地&quot; ⚠&quot;">​</a></h3><p><strong>用户原述</strong>：毛概括解放战争的那句话：「存人失地，人地皆得；存地失人，人地皆失。」翻译到资金上：<strong>本金是「人」，浮盈和账面资产是「地」</strong>。</p><table tabindex="0"><thead><tr><th>侧</th><th>证据</th></tr></thead><tbody><tr><td>毛著侧</td><td><strong>未能在毛著全集中定位</strong>。逐字核过六篇最相关原文 —— 《中共中央关于暂时放弃延安和保卫陕甘宁边区的两个文件》（1946-11 / 1947-04，<strong>最常被归源者</strong>）、《三个月总结》（1946-10-01）、《迎接中国革命的新高潮》（1947-02-01）、《关于西北战场的作战方针》（1947-04-15）、《解放战争第二年的战略方针》（1947-09-01）、《目前形势和我们的任务》（1947-12-25）—— <strong>全部零命中</strong>。→ 判定为<strong>流传性概括 / 文艺化引用</strong>，非毛选逐字原文。</td></tr><tr><td>天涯侧</td><td>手册 <code>05</code> 帖 77（南侠1987）：2015 年 1 月「119 股灾」自有资金 <strong>2100 万 → 1800 万 → 850 万</strong>，补 50 万保证金后仍被强平至 <strong>70 万</strong>；他事后测算：<strong>若预留 300 万机动资金（约本金 15%），本可扛过最低点、账户本可到 8400 万</strong>。</td></tr></tbody></table><p><strong>判定</strong>：<strong>操作层面完全成立</strong>（「300 万机动资金 = 千万级账户的生死线」就是「存人失地」的实盘版：<strong>为了守住账面仓位（地），把本金（人）填了进去</strong>）。但<strong>引文本身不是毛选原文</strong> —— 迁移方法论时，<strong>借其义可以，标其源要谨慎</strong>。</p><p><strong>可替代的更稳出处（已核到逐字）</strong>：同期毛著中语义等价的表述是「<strong>以歼灭敌人有生力量为主要目标，不以保守或夺取城市和地方为主要目标</strong>——保守或夺取城市和地方，是歼灭敌人有生力量的结果」—— <strong>《目前形势和我们的任务》（1947-12-25）十大军事原则第（3）条</strong>，逐字命中（《解放战争第二年的战略方针》1947-09-01 亦有同句）。<strong>要引&quot;弃地保人&quot;这个意思，引这句比引&quot;存人失地&quot;稳得多。</strong></p><hr><h3 id="四、游击战十六字诀-↔-一套完整交易系统-✅-且出处比常识更精确" tabindex="-1">四、游击战十六字诀 ↔ 一套完整交易系统 ✅（且出处比常识更精确） <a class="header-anchor" href="#四、游击战十六字诀-↔-一套完整交易系统-✅-且出处比常识更精确" aria-label="Permalink to &quot;四、游击战十六字诀 ↔ 一套完整交易系统 ✅（且出处比常识更精确）&quot;">​</a></h3><p><strong>用户原述</strong>：敌进我退 / 敌驻我扰 / 敌疲我打 / 敌退我追 ↔ 空仓撤退 / 小仓试错 / 信号确认出手 / 趋势确认持有；配「不打无准备之仗，不打无把握之仗」= 条件触发而非时点押注；「集中优势兵力，各个歼灭敌人」↔ 帖 139「把一件事做透」。</p><table tabindex="0"><thead><tr><th>侧</th><th>证据</th></tr></thead><tbody><tr><td>毛著侧</td><td>《中国革命战争的战略问题》（1936-12）<strong>逐字命中</strong>：「敌进我退」2 次、「敌驻我扰」「敌退我追」各 1 次、「<strong>十六字诀</strong>」4 次。原文：「然而从<strong>一九二八年五月</strong>开始，适应当时情况的带着朴素性质的游击战争基本原则，已经产生出来了，那就是所谓『<strong>敌进我退，敌驻我扰，敌疲我打，敌退我追</strong>』的十六字诀。」</td></tr><tr><td>天涯侧</td><td>手册 <code>05</code> 帖 139（万里依然，2010–2014）：<strong>目标细分法 + 把一件事做透的三步法</strong>、攻心谈判、期货教训 —— 即&quot;集中优势兵力、各个歼灭&quot;。</td></tr></tbody></table><p><strong>判定</strong>：成立。<strong>「集中优势兵力，各个歼灭敌人」= 多数人破产不是因为机会太少，而是同时开了五条战线</strong> —— 这一条与手册 <code>05</code> 的风控链（资金层级、应急资金、单一战场纪律）严丝合缝。</p><blockquote><p>补充精度：十六字诀<strong>不在</strong>《抗日游击战争的战略问题》（1938-05）与《井冈山的斗争》（1928-11）中；<strong>毛著正典出处是 1936 年《中国革命战争的战略问题》</strong>，且毛本人注明其形成于 <strong>1928 年 5 月</strong>。</p></blockquote><hr><h3 id="五、群众路线-↔-「信息跟随群众-仓位警惕群众」✅-且用法需辩证" tabindex="-1">五、群众路线 ↔ 「信息跟随群众，仓位警惕群众」✅（且用法需辩证） <a class="header-anchor" href="#五、群众路线-↔-「信息跟随群众-仓位警惕群众」✅-且用法需辩证" aria-label="Permalink to &quot;五、群众路线 ↔ 「信息跟随群众，仓位警惕群众」✅（且用法需辩证）&quot;">​</a></h3><p><strong>用户原述</strong>：「从群众中来，到群众中去」—— <strong>信息上要去群众中</strong>（20 万页值钱正因它是殡葬师、刑警、老千、炒房人的一手材料）；<strong>行动上要离群众远</strong>（群众蜂拥之处就是山顶）。</p><table tabindex="0"><thead><tr><th>侧</th><th>证据</th></tr></thead><tbody><tr><td>毛著侧</td><td>「从群众中来」1 次、「到群众中去」2 次 —— 出自 <strong>《关于领导方法的若干问题》（1943-06-01）</strong>：「在我党的一切实际工作中，凡属正确的领导，必须是从群众中来，到群众中去。这就是说，将群众的意见（分散的无系统的意见）集中起来（经过研究，化为集中的系统的意见），又到群众中去作宣传解释……」</td></tr><tr><td>天涯侧</td><td>手册 <code>02</code> 七点之一：<strong>权威替代思考</strong>的反面 —— 空军「天天上网看牛刀」是<strong>只听二手结论</strong>；而天涯幸存者的共同动作是<strong>自己去一线核价</strong>（多平台成交价交叉验证、噪音用分贝计实测、楼层朝向现场验证）。</td></tr></tbody></table><p><strong>判定</strong>：成立，且<strong>用户的辩证化是增值</strong>。毛的原文讲的是<strong>双向循环</strong>（群众→集中→回到群众），用户把它拆成两个方向<strong>不同用途</strong>的纪律：<strong>信息向内（到群众中去调研），仓位向外（与群众保持距离）</strong>。这是原题在<strong>投资场景下的正确特化</strong>，值得保留。</p><blockquote><p>⚠ 微调：「从群众中来，到群众中去」的出处是 <strong>1943 年《关于领导方法的若干问题》</strong>，<strong>不是</strong> 1942 年《整顿党的作风》。二者常被混为一谈。</p></blockquote><hr><h3 id="六、《实践论》↔「年度验尸」✅" tabindex="-1">六、《实践论》↔「年度验尸」✅ <a class="header-anchor" href="#六、《实践论》↔「年度验尸」✅" aria-label="Permalink to &quot;六、《实践论》↔「年度验尸」✅&quot;">​</a></h3><p><strong>用户原述</strong>：「实践、认识、再实践、再认识」—— 年度对判断验尸就是把循环制度化；毛 1941 年整风的方法论（批评与自我批评、「惩前毖后，治病救人」）用在个人身上。</p><table tabindex="0"><thead><tr><th>侧</th><th>证据</th></tr></thead><tbody><tr><td>毛著侧</td><td>① 《实践论》（1937-07）<strong>逐字命中</strong>：「<strong>实践、认识、再实践、再认识</strong>，这种形式，循环往复以至无穷，而实践和认识之每一循环的内容，都比较地进到了高一级的程度。」② 「惩前毖后」2 次、「治病救人」2 次 —— 出自 <strong>《整顿党的作风》（1942-02-01）</strong>：「我们反对主观主义、宗派主义、党八股，有两条宗旨是必须注意的：第一是『惩前毖后』，第二是『治病救人』。」</td></tr><tr><td>天涯侧</td><td>手册 <code>04</code> 的<strong>三层命中率记账</strong>（结构层 7–8 成 / 点位层 3 成）+ <code>prediction-ledger.md</code> 的逐帖逐条原始检验台账 —— <strong>就是「实践→认识→再实践」的制度化</strong>：每个预言都留了&quot;当时怎么说的、后来对了没有&quot;。</td></tr></tbody></table><p><strong>判定</strong>：成立。<strong>「知道自己会怎么死的人，很难死」</strong> —— 对错误判决要狠（惩前），对心态要治病救人。</p><blockquote><p>⚠ 微调：整风运动 <strong>1941 年</strong>起（《改造我们的学习》1941-05），但「<strong>惩前毖后，治病救人</strong>」的提法出自 <strong>1942 年 2 月《整顿党的作风》</strong>。说「1941 年搞整风」没错，但把这两句挂到 1941 年不准。</p></blockquote><hr><h2 id="三、勘误表-六类失真框架" tabindex="-1">三、勘误表（六类失真框架） <a class="header-anchor" href="#三、勘误表-六类失真框架" aria-label="Permalink to &quot;三、勘误表（六类失真框架）&quot;">​</a></h2><p>本库 <code>source-verification</code> 的六类失真判据（①时间错位 ②程度夸大 ③主体/口径错位 ④方向读反 ⑤无具名信源 ⑥指标拼接）逐条过筛：</p><table tabindex="0"><thead><tr><th>#</th><th>用户表述</th><th>毛著侧核实</th><th>天涯侧核实</th><th>失真类型</th><th>判定</th></tr></thead><tbody><tr><td>1</td><td>阶级分析开篇 ↔ KK「辨别利益…」</td><td>《中国社会各阶级的分析》1925-12 逐字 ✓</td><td>手册 <code>01</code>【K1】帖 5(kkndme) 逐字 ✓</td><td>—</td><td>✅ 成立</td></tr><tr><td>2</td><td>「诸侯、开发商、炒房客—独独缺中央」</td><td>—</td><td>手册原文为 <strong>7 类主体</strong>，「诸侯」= 地方政府的转述</td><td>ⓒ 主体表述走样（轻微）</td><td>△ 转述</td></tr><tr><td>3</td><td>《论持久战》批亡国论/速胜论</td><td>逐字 ✓（24 / 7 次）</td><td>手册 <code>04</code> 分层命中率 ✓</td><td>—</td><td>✅ 成立</td></tr><tr><td>4</td><td>「战略上藐视…战术上重视」在《论持久战》</td><td>✗ 论持久战零命中；实出自 <strong>1957《一切反动派都是纸老虎》</strong></td><td>—</td><td>ⓐ <strong>时间错位 19 年</strong></td><td>⚠ 需修正</td></tr><tr><td>5</td><td>《论持久战》三阶段 = 防御—相持—反攻</td><td>原文「防御→敌之保守/我之准备反攻→我之反攻」；「相持」为通行简称</td><td>—</td><td>—</td><td>✅ 成立</td></tr><tr><td>6</td><td>「存人失地，人地皆得」为毛概括解放战争</td><td><strong>所核毛著六篇全零命中</strong>（含最常归源的 1946-11/1947-04 暂时放弃延安）；等价原文见十大军事原则（3）</td><td>手册 <code>05</code> 帖 77「300 万机动资金=生死线」✓（操作为真）</td><td>ⓔ 无具名原文出处</td><td>⚠ 属流传性概括</td></tr><tr><td>7</td><td>十六字诀 = 交易系统</td><td>《中国革命战争的战略问题》1936-12 逐字 ✓（毛注明成于 1928-05）</td><td>手册 <code>05</code> 帖 139「做透」✓</td><td>—</td><td>✅ 成立</td></tr><tr><td>8</td><td>「没有调查，没有发言权」= 空军尸检</td><td>《反对本本主义》1930-05 逐字 ✓</td><td>手册 <code>02</code> 七节【41】空军「看牛刀」；<strong>牛刀那句实属帖【40】</strong></td><td>ⓒ 帖号错位（41→40）</td><td>⚠ 需修正</td></tr><tr><td>9</td><td>「从群众中来，到群众中去」</td><td>《关于领导方法的若干问题》1943-06-01 逐字 ✓</td><td>—</td><td>—</td><td>✅ 成立</td></tr><tr><td>10</td><td>「实践、认识、再实践、再认识」</td><td>《实践论》1937-07 逐字 ✓</td><td>手册 <code>04</code> 命中率记账 ✓</td><td>—</td><td>✅ 成立</td></tr><tr><td>11</td><td>1941 整风「惩前毖后，治病救人」</td><td>二语出自 <strong>1942《整顿党的作风》</strong>；整风 1941 起</td><td>—</td><td>ⓐ 年份微调</td><td>△ 微调</td></tr><tr><td>12</td><td>南侠<strong>1987</strong> 两次千万归零</td><td>—</td><td><strong>1987 是用户名</strong>（南侠1987）；两次爆仓均 <strong>2015 年</strong>（1 月 2100万→70万；6 月 70万→5000万→被千股跌停击穿）</td><td>ⓒ <strong>主体/口径错位</strong></td><td>⚠ 需修正</td></tr><tr><td>13</td><td><strong>139</strong> 号帖「三年挣 <strong>850 万</strong>」</td><td>—</td><td>手册中 <strong>850 万属帖 77（南侠）</strong>；139（万里依然）标签为「目标细分法、做透三步、攻心谈判、期货教训」，<strong>无 850 万</strong></td><td>ⓕ <strong>指标拼接（数字搬家）</strong></td><td>⚠ 需修正</td></tr></tbody></table><p><strong>汇总：6 条主干对照全部成立</strong>（论点站得住）；<strong>4 处引用需修正</strong>（#4 年份错位、#6 出处存疑、#8 帖号、#12 主体口径），2 处微调（#11），1 处转述标注（#2），<strong>1 处数字搬家（#13）</strong>。</p><blockquote><p><strong>方法论含义</strong>：这份对照的<strong>结构性判断</strong>（同一认识论在两个时代各自被逼出来）<strong>经得起原文核验</strong>；失真的都在<strong>引文层</strong>（年份、帖号、主体）。恰好印证本库 <code>source-verification</code> 的判断：<strong>论点正确 ≠ 引文正确</strong>，而<strong>引文精度是可迁移性的前提</strong> —— 引错了源，方法就变成了&quot;某大 V 说过&quot;。</p></blockquote><hr><h2 id="四、三条边界-用户提的两条-补一条" tabindex="-1">四、三条边界（用户提的两条 + 补一条） <a class="header-anchor" href="#四、三条边界-用户提的两条-补一条" aria-label="Permalink to &quot;四、三条边界（用户提的两条 + 补一条）&quot;">​</a></h2><p>用户自己划的两条边界<strong>质量很高，直接保留</strong>：</p><ol><li><strong>借认识论，别借斗争论。</strong>「如何认识复杂世界」的那一半（实事求是、矛盾分析、持久战、调查研究）可整体迁移；「如何斗争」的那一半不能带进市场 —— <strong>对手盘不是敌人，是环境</strong>。敌进我退的精髓是「<strong>不打</strong>」，不是「多打」；把每笔交易当作战来打的人，会死于过度交易（抽水 × 频率 = 必输）。</li><li><strong>别把&quot;路线斗争&quot;带回家。</strong> 家庭是统一战线，不是战场 —— 对配偶用「谁是我们的敌人」思维，是这套方法唯一会让人变惨的用法。</li></ol><p><strong>补第三条（本次核实后新增）</strong>：</p><ol start="3"><li><strong>借&quot;利益结构&quot;这个方法，别借&quot;阶级&quot;这个范畴。</strong> 毛的阶级划分锚在 1925 年中国特定的生产关系（地主 / 买办 / 佃农）；<strong>照搬范畴会误判，照搬方法才有效</strong>。用户实际已经在做对了 —— 他用的是「<strong>利益主体 / 目标函数</strong>」而不是「阶级成分」，这正是从<strong>具体范畴</strong>退到<strong>抽象方法</strong>的正确动作，值得显式化。</li></ol><hr><h2 id="五、一条增量洞察-为什么-结构层准、点位层不准" tabindex="-1">五、一条增量洞察：为什么&quot;结构层准、点位层不准&quot; <a class="header-anchor" href="#五、一条增量洞察-为什么-结构层准、点位层不准" aria-label="Permalink to &quot;五、一条增量洞察：为什么&quot;结构层准、点位层不准&quot;&quot;">​</a></h2><p>这是本文最值得带走的一条 —— 它把<strong>天涯的数据</strong>和<strong>毛的认识论</strong>接在同一个机制上：</p><ul><li><strong>手册 <code>04</code> 的实测</strong>：结构层命中 7–8 成，点位层仅 3 成。</li><li><strong>毛的解释</strong>：《论持久战》只预言&quot;最后胜利是中国的&quot;&quot;要打持久战&quot;&quot;必经三个阶段&quot;，<strong>从不预言某城某日</strong>。因为它的推理<strong>只从条件（约束）出发</strong> —— 中日双方的政治、经济、军事、地理条件决定了战争的<strong>结构和阶段</strong>，但<strong>不决定任何具体时点</strong>。</li></ul><p><strong>结论</strong>：<strong>从约束推出的只能是结构，不会是时点。</strong> 天涯高手做对的、也是毛做得最漂亮的，都是同一件事 —— <strong>把&quot;我会不会赢&quot;换成&quot;约束把我逼向哪个结构&quot;</strong>。所以「方向对但早 3 年」不是执行力问题，是<strong>工具的性质</strong>：约束推理在时间轴上天然没有分辨率。凡是号称能同时给方向和点位的人，<strong>要么在骗，要么在下注</strong>。</p><blockquote><p>这也解释了&quot;预测倒过来看&quot;的现象：<strong>点位层的失败不否定结构层的正确</strong>，二者出自同一套推理的不同分辨率。</p></blockquote><hr><h2 id="六、可深挖的接口-后续可做的对照精读" tabindex="-1">六、可深挖的接口（后续可做的对照精读） <a class="header-anchor" href="#六、可深挖的接口-后续可做的对照精读" aria-label="Permalink to &quot;六、可深挖的接口（后续可做的对照精读）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接口</th><th>天涯侧</th><th>毛著侧（已见原文）</th><th>价值</th></tr></thead><tbody><tr><td>结构 vs 时点</td><td>手册 <code>04</code> 三层命中率</td><td>《论持久战》三阶段</td><td>工具的分辨率极限</td></tr><tr><td>验尸制度</td><td><code>prediction-ledger.md</code></td><td>《实践论》循环</td><td>把认识论变成流程</td></tr><tr><td>风险与本金</td><td>手册 <code>05</code> 帖 77 应急资金</td><td>《中国革命战争的战略问题》/ 有生力量</td><td>可替代「存人失地」的稳出处</td></tr><tr><td>利益表 → 站队</td><td>手册 <code>01</code> 帖 5</td><td>《中国社会各阶级的分析》</td><td>决策表的原型</td></tr><tr><td>集中兵力</td><td>手册 <code>05</code> 帖 139 做透三步</td><td>「集中优势兵力，各个歼灭敌人」</td><td>反多线作战</td></tr></tbody></table><hr><h2 id="附-核实日志-可复现" tabindex="-1">附：核实日志（可复现） <a class="header-anchor" href="#附-核实日志-可复现" aria-label="Permalink to &quot;附：核实日志（可复现）&quot;">​</a></h2><ul><li>毛著原文源：<code>https://www.marxists.org/chinese/maozedong/</code>（中文马克思主义文库）。代理 <code>127.0.0.1:8899</code>；直连被墙。</li><li>逐字核过并留存正文的篇目：<code>193805</code>（抗日游击战争的战略问题）、<code>193805b</code>（论持久战）、<code>193005</code>（反对本本主义）、<code>193707</code>（实践论）、<code>19251201</code>（中国社会各阶级的分析）、<code>193612</code>（中国革命战争的战略问题）、<code>19420201</code>（整顿党的作风）、<code>19430601</code>（关于领导方法的若干问题）、<code>19571118a</code>（一切反动派都是纸老虎）、<code>19281125</code>（井冈山的斗争）。</li><li>「存人失地」负向核查：逐字核过 <strong>1946-11/1947-04</strong>（暂时放弃延安 —— <strong>最常被归源者</strong>）、<strong>1946-10-01</strong>、<strong>1947-02-01</strong>、<strong>1947-04-15</strong>、<strong>1947-09-01</strong>、<strong>1947-12-25</strong> 六篇 → <strong>零命中</strong>。</li><li><strong>诚实边界</strong>：1945–49 其余篇目的机械全扫因出境网络抖动未跑完（抽查的六篇已覆盖所有高可能篇目，无证据显示会有命中）—— 故结论写成「<strong>在所核毛著中未见</strong>」，<strong>不宣称&quot;全库已证伪&quot;</strong>。</li></ul><blockquote><p><strong>脚注（不代表原文）</strong>：文中&quot;毛借用给资金管理&quot;的所有映射（本金=人、浮盈=地、三阶段=周期定位、十六字诀=交易纪律）<strong>均为本文的类比构造</strong>，非毛本人观点。<strong>事实（原文）与诠释（映射）必须分开读</strong> —— 这是本库处理激进理论的一贯纪律。</p></blockquote><hr><h2 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h2><p>毛泽东思想、毛选、论持久战、亡国论、速胜论、三个阶段、中国社会各阶级的分析、反对本本主义、实践论、中国革命战争的战略问题、整顿党的作风、关于领导方法的若干问题、一切反动派都是纸老虎、十六字诀、存人失地、从群众中来、惩前毖后治病救人、利益分析、利益分析法、阶级分析、调查研究、持久战、结构层与点位层、跨域方法迁移、引用核实、时间错位、指标拼接、失效条件、公理检验法、可证伪性、不可证伪、五类失真、六类失真、核验方法、信源核实、民间史论、预言命中率、天涯神贴、kkndme、土地财政、杠杆爆仓</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><p><code>topics/tianya/index.md</code>、<code>topics/mao-zedong/class-analysis-friend-enemy.md</code>、<code>topics/mao-zedong/mao-philosophy-practice-contradiction.md</code>、<code>topics/mao-zedong/mao-collected-works.md</code>、<code>topics/tianya/prediction-ledger.md</code>、<code>topics/tianya/handbook/04_趋势预测方法论.md</code>、<code>topics/tianya/handbook/01_房价与土地财政的底层逻辑.md</code>、<code>topics/ai-brain/knowledge-system-arsenal.md</code>、<code>topics/science-news/</code>（可证伪性↔核验方法）</p>',76)])])}const q=o(s,[["render",g]]);export{u as __pageData,q as default};
